import{z as s,x as B,o as e,c as m,q as i,j as n,D as A,d as t,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"均值方差何时等于 EU","description":"","frontmatter":{"title":"均值方差何时等于 EU","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mean-variance-eu.md","filePath":"econ/mean-variance-eu.md","lastUpdated":1791063341000}'),u={name:"econ/mean-variance-eu.md"};function p(C,a,d,D,h,b){const r=B("Mermaid");return e(),m("div",null,[a[2]||(a[2]=i('<h1 id="均值方差何时等于-eu" tabindex="-1">均值方差何时等于 EU <a class="header-anchor" href="#均值方差何时等于-eu" aria-label="Permalink to &quot;均值方差何时等于 EU&quot;">​</a></h1><div class="epigraph"><p>用均值与方差排序，只在效用是二次、或分布被这两个数字完全钉住时，才与期望效用是同一问题。</p><footer>—— 据 Markowitz, Portfolio Selection, Journal of Finance, 1952；对照 von Neumann–Morgenstern 表示</footer></div><p><a href="/econ/background-risk">上一课</a>（背景风险）。钉了 CARA / CRRA / DARA 的形状。本课不重写这些微分方程，也不把 \\(r_A\\) 再定义一遍。缺口是：资产配置文献常把目标直接写成 \\(V(\\mu,\\sigma)\\)。这在一般 \\(u\\) 与一般分布下并不等于 \\(\\mathbb{E}u\\)。必须标明两条——也几乎只有两条——使均值方差成为期望效用的充分统计，而不是另起一套偏好。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>vNM 的对象是整条分布。均值与方差是两个数字。若没有额外结构，两个分布可以 \\(\\mu\\)、\\(\\sigma\\) 相同而 \\(\\mathbb{E}u\\) 不同，也可以 \\(\\sigma\\) 更大但被所有凹 \\(u\\) 喜欢（偏度、支撑作怪）。缺口因此不是「要不要分散」，而是问：何时存在 \\(V\\)，使</p> \\[\\mathbb{E}\\,u(\\tilde w)=V\\bigl(\\mathbb{E}\\tilde w,\\mathrm{Var}(\\tilde w)\\bigr) \\]<p>对所考虑的菜单成立。答案是刀刃：要么 \\(u\\) 是二次，要么分布族被 \\((\\mu,\\sigma)\\) 参数化——正态是最常用的一员。Markowitz 的均值方差分析是这条刀刃上的算法，不是对 EU 的一般改写。本课不写组合实证，不把有效前沿拿去拟合收益。</p><p>二次效用 \\(u(w)=w-bw^2\\) 只依赖一、二阶矩，但 \\(r_A\\) 递增且存在餍足，与上一课的 DARA 工作假设冲突。故它是数学特例，不是主干偏好。</p><p><span class="marginnote">二次效用在 \\(w=1/(2b)\\) 处到顶：比这更富，「效用」反而开始下降，这一段叫餍足区。初学者容易把它当成日常可用的偏好，实际上它只是让均值和方差两个数字够用的数学特例，不是对风险态度的真实刻画。</span></p><h3 id="正态加-cara-是另一条刀刃-不是二次" tabindex="-1">正态加 CARA 是另一条刀刃，不是二次 <a class="header-anchor" href="#正态加-cara-是另一条刀刃-不是二次" aria-label="Permalink to &quot;正态加 CARA 是另一条刀刃，不是二次&quot;">​</a></h3><p>若 \\(\\tilde w\\) 正态且 \\(u\\) 是 CARA，则 \\(\\mathbb{E}u\\) 是 \\(\\mu-\\tfrac12\\alpha\\sigma^2\\) 的单调变换。此时均值方差来自分布加形状，不是来自二次。CRRA 加对数正态在乘法冲击上有类似封闭解，但一般加法组合不是椭圆，EU 不能收成 \\((\\mu,\\sigma)\\)。不要把「正态」写成「任意钟形」。</p><p><span class="marginnote">椭圆分布族（正态是其中一员）使任意凹增的 \\(u\\) 在该族内的排序都是均值方差。族一离开，同一 \\(u\\) 会在偏度上分裂。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检验两条路。路一：看 \\(u\\) 是否二次——只对没有餍足区的财富水平、且接受 IARA 时可用。路二：把菜单限制在正态（或椭圆）线性组合上，再选 CARA 或任意只通过 \\((\\mu,\\sigma)\\) 进入的 \\(V\\)。两条路都是对<strong>对象</strong>加约束，不是对独立性加约束。</p><p>若两条都不成立，均值方差可以与 EU 反向。后课<a href="/econ/stochastic-dominance">随机占优</a>会给出不指定 \\(u\\) 的偏序；方差更小既非 SOSD 的定义，也不是 MPS。本课先把「MV = EU」的许可证钉死，以免后课把 Markowitz 图当成一般风险厌恶。</p>',15)),(e(),n(l,null,{default:A(()=>[o(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%20E%20u%22%5D%20--%3E%20Q%5B%22u%20%E4%BA%8C%E6%AC%A1%22%5D%0A%20%20EU%20--%3E%20N%5B%22%E5%88%86%E5%B8%83%E7%94%B1%20%CE%BC%E3%80%81%CF%83%20%E9%92%89%E4%BD%8F%22%5D%0A%20%20Q%20--%3E%20MV%5B%22V(%CE%BC%2C%CF%83)%20%E5%90%88%E6%B3%95%22%5D%0A%20%20N%20--%3E%20MV%0A%20%20MV%20--%3E%20MK%5B%22Markowitz%EF%BC%9A%E8%AF%A5%E5%88%80%E5%88%83%E4%B8%8A%E7%9A%84%E7%AE%97%E6%B3%95%22%5D%0A%20%20EU%20--%3E%20NO%5B%22%E4%B8%80%E8%88%AC%20u%E3%80%81%E4%B8%80%E8%88%AC%E5%88%86%E5%B8%83%EF%BC%9AMV%20%E4%B8%8D%E5%A4%9F%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"本课不引入 \\(\\beta\\)、市场组合或样本协方差。那些是定价课与量化栏的对象。这里只问表示何时塌成两个数字。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"二次的机制是泰勒在二阶截断且余项恒为零。正态的机制是分布被两个参数穷尽，任意积分 \\(\\mathbb{E}u\\) 都是 \\((\\mu,\\sigma)\\) 的函数。二者看起来像同一张图，来源不同：一个砍效用，一个砍世界。",-1)),a[6]||(a[6]=E("p",null,"与 CARA/CRRA 的接口：CARA+正态给出线性的均值方差权衡，绝对风险需求与财富无关，和上一课一致。CRRA+正态一般没有闭式 \\(V(\\mu,\\sigma)\\) 作为欧氏均值方差。把幂效用塞进 Markowitz 程序，是偷换了目标。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"数字实例：取 \\(\\alpha=2\\)、\\(\\sigma^2=0.04\\)，CARA 加正态下的确定性等价扣减是 \\(\\tfrac12\\alpha\\sigma^2=0.04\\)，即财富的 4%；风险厌恶翻倍到 \\(\\alpha=4\\)，扣减变 8%。均值方差目标里那条权衡斜率，就是这一个数。")],-1)),(e(),n(l,null,{default:A(()=>[o(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22%E9%97%AE%E9%A2%98%3A%20%E4%BD%95%E6%97%B6%20V(%CE%BC%2C%CF%83)%20%E7%AD%89%E4%BA%8E%20E%20u%22%5D%20--%3E%20CUTU%5B%22%E8%B7%AF%E4%B8%80%3A%20%E7%A0%8D%E6%95%88%E7%94%A8%22%5D%0A%20%20TGT%20--%3E%20CUTW%5B%22%E8%B7%AF%E4%BA%8C%3A%20%E7%A0%8D%E4%B8%96%E7%95%8C%22%5D%0A%20%20CUTU%20--%3E%20QUAD%5B%22u%20%E4%BA%8C%E6%AC%A1%3A%20%E6%B3%B0%E5%8B%92%E4%BA%8C%E9%98%B6%E6%88%AA%E6%96%AD%2C%20%E4%BD%99%E9%A1%B9%E6%81%92%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20QUAD%20--%3E%20C1%5B%22%E4%BB%A3%E4%BB%B7%3A%20r_A%20%E9%80%92%E5%A2%9E%20%2B%20%E9%A4%8D%E8%B6%B3%E5%8C%BA%22%5D%0A%20%20CUTW%20--%3E%20NORM%5B%22%E5%88%86%E5%B8%83%E6%AD%A3%E6%80%81%2F%E6%A4%AD%E5%9C%86%3A%20%E4%B8%A4%E5%8F%82%E6%95%B0%E7%A9%B7%E5%B0%BD%E4%B8%80%E5%88%87%E4%BF%A1%E6%81%AF%22%5D%0A%20%20NORM%20--%3E%20CARA%5B%22%E9%85%8D%20CARA%3A%20E%20u%20%E6%98%AF%20%CE%BC%20-%20%CE%B1%CF%83%C2%B2%2F2%20%E7%9A%84%E5%8D%95%E8%B0%83%E5%8F%98%E6%8D%A2%22%5D%0A%20%20CARA%20--%3E%20C2%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E7%BB%9D%E5%AF%B9%E9%A3%8E%E9%99%A9%E9%9C%80%E6%B1%82%E4%B8%8D%E9%9A%8F%E8%B4%A2%E5%AF%8C%E5%8F%98%22%5D%0A%20%20C1%20--%3E%20MV%5B%22%E4%B8%A4%E6%9D%A1%E5%88%80%E5%88%83%E4%B8%8A%2C%20MV%20%E4%B8%8E%20EU%20%E5%90%8C%E5%BA%8F%22%5D%0A%20%20C2%20--%3E%20MV%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<p><span class="marginnote">Markowitz 1952 自己把效用当背景动机，计算走的是 \\((\\mu,\\sigma)\\)。引用时不要把它写成拒绝 vNM，也不要写成 CAPM 实证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>近似：小风险下 Pratt 的局部溢价只用到方差，那是无穷小，不是有限菜单上的表示等式。大风险、偏度、跳跃，MV 排序可以误导。本课把「局部 ≈」与「全局 =」分开。</p><p><span class="marginnote">Pratt 的局部溢价只在无穷小风险附近才只看方差；初学者容易把「小风险下方差近似够用」悄悄升级成「方差永远够用」。偏度一大，两个均值与方差完全相同的分布，可以一个该选、一个不该选——这正是要把「局部 ≈」与「全局 =」分开的原因。</span></p><p>不完全市场、约束、非交易的劳动收入，会让可交易财富的边际分布不再正态，即使冲击原本是正态。刀刃更窄。也不要把有效前沿画成限价簿上的可成交组合：这里没有报价，只有给定分布族上的选择。</p><p>后课随机占优不依赖二次或正态。那是把本课的「两个数字不够」接下去：用整条分布的积分条件说话。</p><p>后课默认：均值方差等于 EU，仅当二次效用或（椭圆）分布被 \\((\\mu,\\sigma)\\) 参数化；Markowitz 是该特例的算法，不是一般风险偏好。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一般 \\(\\mathbb{E}u\\) 不能收成 \\(V(\\mu,\\sigma)\\)；二次 \\(u\\) 或正态/椭圆族是许可证。</li><li>二次带来 IARA 与餍足，与 DARA 主干不合。</li><li>CARA+正态是另一条合法刀刃，不等于二次。</li><li>本课不写组合实证；下一课用不指定 \\(u\\) 的占优处理一般分布。</li><li>出处：Markowitz, <em>Journal of Finance</em>, 1952；von Neumann and Morgenstern, 1944。</li></ul>',9))])}const f=s(u,[["render",p]]);export{g as __pageData,f as default};
